<?php
require "../includes/auth.php";require "../config/database.php";$page_title="Rekam Medis";$active="rekam";
if(isset($_GET["delete"])){$conn->query("DELETE FROM rekam_medis WHERE id=".(int)$_GET["delete"]);header("Location: rekam_medis.php");exit;}
$edit=null;if(isset($_GET["edit"]))$edit=$conn->query("SELECT * FROM rekam_medis WHERE id=".(int)$_GET["edit"])->fetch_assoc();
if(isset($_POST["save"])){$id=(int)$_POST["id"];$pid=(int)$_POST["pasien_id"];$did=(int)$_POST["dokter_id"];$tgl=$conn->real_escape_string($_POST["tanggal"]);$diag=$conn->real_escape_string($_POST["diagnosis"]);$tin=$conn->real_escape_string($_POST["tindakan"]);$sql=$id?"UPDATE rekam_medis SET pasien_id=$pid,dokter_id=$did,tanggal='$tgl',diagnosis='$diag',tindakan='$tin' WHERE id=$id":"INSERT INTO rekam_medis(pasien_id,dokter_id,tanggal,diagnosis,tindakan)VALUES($pid,$did,'$tgl','$diag','$tin')";$conn->query($sql);header("Location: rekam_medis.php");exit;}require "../includes/header.php";?>
<div class="page-head"><div><div class="eyebrow">MEDIS</div><h1>Rekam Medis</h1><p>Riwayat pemeriksaan dan tindakan pasien.</p></div><a class="btn primary" href="?action=add">＋ Tambah Rekam</a></div>
<?php if(isset($_GET["action"])||$edit):?><div class="panel form-panel"><div class="panel-head"><h3><?=$edit?"Edit Rekam Medis":"Tambah Rekam Medis"?></h3><a href="rekam_medis.php">×</a></div><form method="post"><input type="hidden" name="id" value="<?=$edit["id"]??0?>"><div class="form-grid"><label>Pasien<select name="pasien_id"><?php $q=$conn->query("SELECT * FROM pasien ORDER BY nama");while($x=$q->fetch_assoc()):?><option value="<?=$x["id"]?>" <?=($edit["pasien_id"]??"")==$x["id"]?"selected":""?>><?=$x["nama"]?></option><?php endwhile;?></select></label><label>Dokter<select name="dokter_id"><?php $q=$conn->query("SELECT * FROM dokter ORDER BY nama");while($x=$q->fetch_assoc()):?><option value="<?=$x["id"]?>" <?=($edit["dokter_id"]??"")==$x["id"]?"selected":""?>><?=$x["nama"]?></option><?php endwhile;?></select></label><label>Tanggal<input type="date" name="tanggal" required value="<?=$edit["tanggal"]??date("Y-m-d")?>"></label><label>Diagnosis<input name="diagnosis" required value="<?=htmlspecialchars($edit["diagnosis"]??"")?>"></label><label class="wide">Tindakan<textarea name="tindakan" required><?=htmlspecialchars($edit["tindakan"]??"")?></textarea></label></div><div class="actions"><a class="btn outline" href="rekam_medis.php">Batal</a><button class="btn primary" name="save">Simpan</button></div></form></div><?php endif;?>
<div class="panel"><table><thead><tr><th>Pasien</th><th>Tanggal</th><th>Dokter</th><th>Diagnosis</th><th>Tindakan</th><th>Aksi</th></tr></thead><tbody><?php $q=$conn->query("SELECT r.*,p.nama pasien,d.nama dokter FROM rekam_medis r JOIN pasien p ON p.id=r.pasien_id JOIN dokter d ON d.id=r.dokter_id ORDER BY r.tanggal DESC");while($r=$q->fetch_assoc()):?><tr><td><b><?=$r["pasien"]?></b></td><td><?=date("d M Y",strtotime($r["tanggal"]))?></td><td><?=$r["dokter"]?></td><td><?=$r["diagnosis"]?></td><td><?=$r["tindakan"]?></td><td class="actions-cell"><a class="edit" href="?edit=<?=$r["id"]?>">Edit</a><a class="delete" onclick="return confirm('Hapus rekam medis?')" href="?delete=<?=$r["id"]?>">Hapus</a></td></tr><?php endwhile;?></tbody></table></div><?php require "../includes/footer.php";?>